// MineBench v13: Choo-Choo Train - 4-4-0 American steam locomotive + tender + cars
// Budget: 80000 blocks | Grid: 256 | Palette: simple | Seed: 123
// Key: hollow structures, no solid fills, tight smoke

var G=256, GY=4, GZ=128;
var IR='iron_block',DI='gray_wool',BK='black_wool',WD='oak_planks',LG='oak_log';
var BR='bricks',CL='black_wool',GL='glass',ST='white_wool',GD='gold_block';
var SB='stone_bricks',GR='stone',CB='cobblestone',RD='red_wool',YL='yellow_wool';
var WH='white_wool',OR='orange_wool',PU='purple_wool',BL='brown_wool';
var LV='oak_leaves',GS='grass_block',SD='sand';

function B(x,y,z,t){
  x=Math.trunc(x);y=Math.trunc(y);z=Math.trunc(z);
  if(x>=0&&x<256&&y>=0&&y<256&&z>=0&&z<256) block(x,y,z,t);
}
function bx(x1,y1,z1,x2,y2,z2,t){
  x1=Math.trunc(x1);y1=Math.trunc(y1);z1=Math.trunc(z1);
  x2=Math.trunc(x2);y2=Math.trunc(y2);z2=Math.trunc(z2);
  var ax1=Math.min(x1,x2),ax2=Math.max(x1,x2);
  var ay1=Math.min(y1,y2),ay2=Math.max(y1,y2);
  var az1=Math.min(z1,z2),az2=Math.max(z1,z2);
  for(var x=ax1;x<=ax2;x++) for(var y=ay1;y<=ay2;y++) for(var z=az1;z<=az2;z++) B(x,y,z,t);
}
function cz(cx,cy,cz,r,t,d){
  d=d||1; var r2=r*r;
  for(var dx=-r;dx<=r;dx++) for(var dy=-r;dy<=r;dy++) {
    if(dx*dx+dy*dy<=r2) for(var dz=0;dz<d;dz++) B(cx+dx,cy+dy,cz+dz,t);
  }
}
function cx(x0,y,z,r,n,t){ for(var x=x0;x<x0+n;x++) cz(x,y,z,r,t,1); }
function ring(x,y,z,r,t,w){
  w=w||1;
  for(var dx=-r;dx<=r;dx++) for(var dy=-r;dy<=r;dy++){
    var d2=dx*dx+dy*dy;
    if(d2<=r*r&&d2>(r-1.5)*(r-1.5)){
      for(var dw=0;dw<w;dw++) B(x+dx,y+dy,z+dw,t);
    }
  }
}
function hollow_cyl(x0,y,z,r,t,h,w){
  w=w||1;
  for(var dx=-r;dx<=r;dx++) for(var dy=-r;dy<=r;dy++){
    var d2=dx*dx+dy*dy;
    if(d2<=r*r&&d2>(r-1.2)*(r-1.2)){
      for(var dz=0;dz<h;dz++) B(x0+dx,y+dy,z+dz,t);
    }
  }
}
function sphere(x,y,z,r,t){
  var r2=r*r;
  for(var dx=-r;dx<=r;dx++) for(var dy=-r;dy<=r;dy++) for(var dz=-r;dz<=r;dz++){
    if(dx*dx+dy*dy+dz*dz<=r2) B(x+dx,y+dy,z+dz,t);
  }
}

// === ENVIRONMENT ===

// Gravel bed (trimmed)
for(var x=15;x<248;x++) for(var z=100;z<160;z++){
