function tree(tx,ty,tz){
  bx(tx,ty,tz,tx,ty+5,tz,LG);
  for(var dx=-3;dx<=3;dx++) for(var dz=-3;dz<=3;dz++){
    var d2=dx*dx+dz*dz;
    if(d2<=9){
      B(tx+dx,ty+6,tz+dz,LV);
      B(tx+dx,ty+7,tz+dz,LV);
      B(tx+dx,ty+8,tz+dz,LV);
    }
  }
}
tree(25,GY,158); tree(65,GY,160); tree(95,GY,164);
