// === LOCOMOTIVE ===

var LY=7,LR=4,DY=7,DR=6,TY=6,TR=3;
var SP=115,SR=141; // side panel z positions (visible from side)

// --- Side panels with VISIBLE wheel outlines (key fix for render visibility) ---
function wheelCircle(sx,sy,sz,r,t){
  // Draw a ring + spokes on the side panel
  for(var dx=-r;dx<=r;dx++) for(var dy=-r;dy<=r;dy++){
    var d2=dx*dx+dy*dy;
    if(d2<=r*r&&d2>(r-1.3)*(r-1.3)){
      B(sx+dx,sy+dy,sz,t); // rim
    }
    if(d2<=r*r&&d2>1&&d2<(r-0.5)*(r-0.5)){
      // Spokes at cardinal directions
      if((dx===0)||(dy===0)){
        var step=r;
        while(step>0){
          if((dx===0&&Math.abs(dy)===step)||(dy===0&&Math.abs(dx)===step)){
            B(sx+dx,sy+dy,sz,t);
          }
          step-=Math.max(1,Math.floor(r/3));
        }
      }
    }
  }
  B(sx,sy,sz,t); // hub
}
// Left side panel (iron backing)
